import numpy as np
import io
from scipy.io.matlab import savemat, loadmat

# Test with a char array of dtype U1 (single code points)
d = {
    "char_array": np.array([list("char"), list("char")], dtype="U1"),
}

buf = io.BytesIO()
try:
    savemat(buf, d, format="4")
    print("savemat succeeded")
except Exception as e:
    print(f"savemat failed: {type(e).__name__}: {e}")

